//#region src/io/utilities.js
function downloadFile(data, fName, extension) {
	const filename = _checkFileExtension(fName, extension)[0];
	let saveData = data;
	if (!(saveData instanceof Blob)) saveData = new Blob([data]);
	if (document) {
		const url = URL.createObjectURL(saveData);
		const link = document.createElement("a");
		link.href = url;
		link.download = filename;
		link.click();
		URL.revokeObjectURL(url);
	}
}
function _checkFileExtension(filename, extension) {
	if (!extension || extension === true || extension === "true") extension = "";
	if (!filename) filename = "untitled";
	let ext = "";
	if (filename && filename.includes(".")) ext = filename.split(".").pop();
	if (extension) {
		if (ext !== extension) {
			ext = extension;
			filename = `${filename}.${ext}`;
		}
	}
	return [filename, ext];
}
//#endregion
export { _checkFileExtension, downloadFile };
